INSERT INTO quest (quest_set_id, order_index, title, description, hint, solution, setup_cmd, grade_cmd, kind, choices, answer_index, explanation, answer_spec, template, checks, docs) VALUES
  (405, 1, 'A 레코드', 'DNS 의 **A 레코드** 는 무엇일까요?', '호스트 주소예요.', NULL, NULL, '[]', 'choice', '["별칭이 가리키는 정식 이름", "메일 교환 서버", "호스트의 주소(IPv4)", "권한 있는 네임서버"]', 2, 'RFC 1035 는 A 를 호스트 주소(TYPE 1)로 설명합니다. 별칭은 CNAME, 메일은 MX, 권한 네임서버는 NS 입니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 2, 'CNAME', '**CNAME** 레코드는 무엇을 나타낼까요?', '별칭이에요.', NULL, NULL, '[]', 'choice', '["호스트의 IP 주소", "별칭의 정식(canonical) 이름", "존의 권한이 시작되는 지점", "도메인 이름을 가리키는 역방향 포인터"]', 1, 'RFC 1035 는 CNAME 을 별칭에 대한 정식 이름(TYPE 5)으로 설명합니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 3, 'PTR', '**PTR** 레코드는 무엇에 쓰일까요?', '포인터예요.', NULL, NULL, '[]', 'choice', '["도메인 이름 포인터(역방향 조회)", "호스트의 IPv4 주소를 가리킨다", "텍스트 문자열을 담아 둔다", "메일을 받을 서버를 가리킨다"]', 0, 'RFC 1035 는 PTR 을 도메인 이름 포인터(TYPE 12)로 설명합니다. 주소에서 이름을 찾는 역방향 조회에 쓰입니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 4, 'MX', '**MX** 레코드는 무엇을 가리킬까요?', '메일이에요.', NULL, NULL, '[]', 'choice', '["웹 서버의 IP 주소", "권한 있는 네임서버", "도메인의 소유자 연락 정보", "메일 교환 서버"]', 3, 'RFC 1035 는 MX 를 메일 교환(TYPE 15)으로 설명합니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 5, 'SOA', '**SOA** 레코드는 무엇을 나타낼까요?', '존의 시작이에요.', NULL, NULL, '[]', 'choice', '["도메인의 별칭을 정의한다", "메일 전달 우선순위를 정한다", "존(zone) 권한의 시작을 표시한다", "이름의 역방향 주소를 정한다"]', 2, 'RFC 1035 는 SOA 를 권한 존의 시작을 표시하는 레코드(TYPE 6)로 설명하며, SERIAL·REFRESH·RETRY·EXPIRE·MINIMUM 필드를 가진다고 합니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 6, 'TTL 의 뜻', 'DNS 레코드의 **TTL** 은 무엇을 정할까요?', '캐시 시간이에요.', NULL, NULL, '[]', 'choice', '["레코드가 건너갈 수 있는 최대 홉 수", "캐시할 수 있는 시간(초)", "질의에 응답해야 하는 제한 시간", "레코드가 가질 수 있는 최대 크기"]', 1, 'RFC 1035 는 TTL 이 32비트 부호 없는 정수로, 리소스 레코드를 버려야 하기 전까지 캐시할 수 있는 시간(초)을 뜻한다고 설명합니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 7, 'TTL 0', 'TTL 이 **0** 이면 어떻게 다뤄질까요?', '캐시하지 않아요.', NULL, NULL, '[]', 'choice', '["캐시하지 않고 그때만 쓴다", "영구히 캐시해 두고 쓴다 (무제한)", "삭제된 레코드로 간주해 버린다", "기본 TTL 로 자동 대체해서 쓴다"]', 0, 'RFC 1035 는 TTL 0 이 그 레코드를 현재 진행 중인 트랜잭션에만 쓰고 캐시하지 않아야 한다는 뜻이라고 설명합니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 8, 'UDP 크기 제한', '전통적인 DNS 의 **UDP 메시지** 는 얼마까지이며 넘으면 어떻게 될까요?', '512바이트예요.', NULL, NULL, '[]', 'choice', '["1500바이트로 제한되고 넘으면 오류가 난다", "제한이 없고 항상 분할 전송된다", "64KB 로 제한되고 넘으면 TCP 로 바뀐다", "512바이트로 제한되고 넘으면 잘리며 TC 비트가 설정된다"]', 3, 'RFC 1035 는 UDP 메시지가 512바이트로 제한되고 더 길면 잘리며 TC(Truncation) 비트가 설정된다고 설명합니다. 이때 클라이언트는 TCP 로 다시 질의할 수 있습니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 9, '이름 길이 제한', 'DNS 에서 **레이블 하나와 전체 이름** 의 최대 길이는 얼마일까요?', '63 과 255 예요.', NULL, NULL, '[]', 'choice', '["레이블 255, 전체 이름 63 옥텟", "레이블 32, 전체 이름 128 옥텟", "레이블 63, 전체 이름 255 옥텟", "레이블 253, 전체 이름 1024 옥텟"]', 2, 'RFC 1035 는 레이블이 63 이하이고, 전체 도메인 이름이 길이 옥텟을 포함해 255 옥텟 이하라고 설명합니다.', NULL, NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 10, '권한 네임서버 레코드', '존의 **권한 있는 네임서버** 를 가리키는 레코드 타입입니다. 빈칸을 채우세요.', '"name server" 의 줄임이에요.', NULL, NULL, '[]', 'fill', '["NS", "A", "MX", "TXT"]', NULL, 'NS 는 권한 있는 네임서버를 가리키는 레코드(TYPE 2)입니다.', '[0]', 'example.com. IN {0} ns1.example.com.', NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 11, 'DNS 포트', 'DNS 네임서버가 쓰는 **포트 번호** 입니다(UDP 와 TCP). 빈칸을 채우세요.', '두 자리 숫자예요.', NULL, NULL, '[]', 'fill', '["53", "80", "153", "5353"]', NULL, 'RFC 1035 는 네임서버가 TCP 와 UDP 의 53번 포트를 쓴다고 설명합니다.', '[0]', 'dig @ns1.example.com -p {0} example.com', NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]'),
  (405, 12, '재귀 질의의 흐름', '재귀 질의가 처리되는 큰 줄기 순서입니다. 순서에 맞게 놓아 보세요.', '요청 → 처리 → 응답 → 캐시예요.', NULL, NULL, '[]', 'order', '["클라이언트가 RD(재귀 요청) 비트를 켠 질의를 보낸다", "재귀를 지원하는 네임서버가 답을 찾아 나선다", "서버가 RA(재귀 가능) 비트를 켠 응답을 돌려준다", "레코드는 TTL 동안 캐시된다"]', NULL, 'RFC 1035 의 RD·RA 비트와 TTL 설명을 이은 큰 줄기입니다. 재귀 지원은 선택 사항입니다.', '[0, 1, 2, 3]', NULL, NULL, '[{"title": "RFC 1035 DNS", "url": "https://www.rfc-editor.org/rfc/rfc1035"}]');
